/* Survival objects are additions to the original NatureWorld, never a replacement terrain renderer. */
(()=>{'use strict';
const T=THREE,D=SurvivalData,W=EmberTerrain,{hash,ground,biome,inCave,islands}=W;
const geo={box:new T.BoxGeometry(1,1,1,2,2,2),sphere:new T.SphereGeometry(1,20,14),rock:new T.IcosahedronGeometry(1,2),cylinder:new T.CylinderGeometry(1,1,1,16),cone:new T.ConeGeometry(1,1,12),shard:new T.IcosahedronGeometry(1,0),leaf:new T.CircleGeometry(1,5),ring:new T.TorusGeometry(1,.09,12,64)};
const textureByColor={
 '#775741':'timber','#8b6444':'timber','#704830':'timber','#8e7255':'timber','#68523f':'timber','#a48660':'timber','#98734e':'timber','#94704b':'timber','#856246':'timber','#79583f':'timber',
 '#a8b8b8':'forged-iron','#cfdfdb':'forged-iron','#abc5cb':'forged-iron','#50616a':'forged-iron',
 '#c4aa6e':'brass','#c7aa61':'brass','#c1ac75':'brass','#a79565':'brass',
 '#858881':'moss-stone','#707b79':'moss-stone','#8e9c99':'moss-stone','#354d50':'moss-stone','#4b6869':'ancient-runes','#467c77':'shingles',
 '#9b9c91':'cave-limestone','#8a92a0':'forged-iron','#95c4f8':'blue-crystal','#c9e4dc':'blue-crystal','#dbc296':'leather','#738f8a':'leather'};
class World{
 constructor(scene){this.scene=scene;this.static=new T.Group();scene.add(this.static);this.dynamic=new T.Group();scene.add(this.dynamic);this.nativeRoot=new T.Group();scene.add(this.nativeRoot);this.native=new NatureWorld(this.nativeRoot);this.nativeRoot.position.set(-W.anchor.x,-W.anchor.y,-W.anchor.z);
 this.materials=new Map();this.resources=[];this.resourceChunks=new Map();this.colliders=[];this.deco=[];this.loader=new T.TextureLoader();this.textures={};for(const id of ['cave-limestone','sandstone','ancient-runes','timber','shingles','forged-iron','brass','leather','blue-crystal','obsidian','moss-stone','bone','scale-hide','wild-fur']){const t=this.loader.load('assets/survival/materials/'+id+'.png');t.wrapS=t.wrapT=T.RepeatWrapping;t.encoding=T.sRGBEncoding;t.anisotropy=4;this.textures[id]=t;}
 const clear=(x,z)=>this.native.destinations.push({east:x+W.anchor.x,north:z+W.anchor.z});if(W.bossContentEnabled){for(const s of Object.values(W.sites))clear(s.x,s.z);for(let x=-12;x<=12;x+=12)for(let z=-12;z<=12;z+=12)clear(x,z);for(let x=-24;x<=24;x+=12)for(let z=-24;z<=24;z+=12)clear(W.sites.cave.x+x,W.sites.cave.z+z);}clear(W.shop.x,W.shop.z);
 this.textures.bark=this.native.originals.bark;this.build();}
 mat(color,glow=false,texture){texture=texture||textureByColor[color];const key=color+glow+(texture||'');if(!this.materials.has(key))this.materials.set(key,new T.MeshStandardMaterial({color:new T.Color(color).lerp(new T.Color('#ffffff'),texture?.72:0).convertSRGBToLinear(),map:this.textures[texture]||null,bumpMap:this.textures[texture]||null,bumpScale:texture?.035:0,roughness:texture==='forged-iron'?.45:texture==='brass'?.42:.9,metalness:texture==='forged-iron'||texture==='brass'?.5:0,emissive:glow?new T.Color(color).convertSRGBToLinear():texture?new T.Color('#ffffff'):0,emissiveMap:this.textures[texture]||null,emissiveIntensity:glow?.32:texture?.07:0}));return this.materials.get(key);}
 mesh(parent,kind,color,x,y,z,sx=1,sy=1,sz=1,glow=false,texture){let geometry=geo[kind];if((texture||textureByColor[color])&&kind==='box'){geometry=geometry.clone();const uv=geometry.attributes.uv,pos=geometry.attributes.position,norm=geometry.attributes.normal;for(let i=0;i<uv.count;i++){const nx=Math.abs(norm.getX(i)),ny=Math.abs(norm.getY(i));uv.setXY(i,(nx>.5?pos.getZ(i)*sz:pos.getX(i)*sx)/2,(ny>.5?pos.getZ(i)*sz:pos.getY(i)*sy)/2);}}else if((texture||textureByColor[color])&&kind==='cylinder'){geometry=geometry.clone();const uv=geometry.attributes.uv,pos=geometry.attributes.position,norm=geometry.attributes.normal;for(let i=0;i<uv.count;i++){if(Math.abs(norm.getY(i))>.5)uv.setXY(i,pos.getX(i)*sx/3,pos.getZ(i)*sz/3);else uv.setXY(i,uv.getX(i)*Math.PI*Math.max(sx,sz),uv.getY(i)*sy/2);}}const m=new T.Mesh(geometry,this.mat(color,glow,texture));m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
 group(x=0,y=0,z=0,parent=this.static){const g=new T.Group();g.position.set(x,y,z);parent.add(g);return g;}
 tube(parent,points,r,color,texture){const curve=new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p)));const geometry=new T.TubeGeometry(curve,18,r,7,false),m=new T.Mesh(geometry,this.mat(color,false,texture));m.castShadow=true;m.receiveShadow=true;m.userData.transientGeometry=true;parent.add(m);return m;}
 build(){
 // Hand-placed beginner habitats: branches on fallen wood and flakes beside an exposed rock.
 for(const [id,k,x,z] of [['start0','wood',-17,26],['start1','wood',-13,31],['start2','stone',-9,26],['start3','stone',-5,31],['start4','fiber',2,32],['start5','berry',22,31]])this.resource(id,k,x,ground(x,z),z,biome(x,z,ground(x,z)),{type:k==='wood'?'deadwood':k==='stone'?'outcrop':k==='berry'?'shrub':'grass'});
 // Mineral veins and fungi follow the cave walls, leaving the entrance and floor open.
 if(W.bossContentEnabled)for(let n=0;n<15;n++){const side=n%3,x=W.sites.cave.x+(side===0?-15:side===1?15:-12+(n/3|0)*6),z=W.sites.cave.z+(side===2?-15:-12+(n/3|0)*6);const k=n%3===0?'ore':n%3===1?'crystal':'spore';const node=this.resource('cavewall-'+n,k,x,W.caveY,z,'cave',{type:'cave-wall'});node.root.rotation.y=side===0?Math.PI/2:side===1?-Math.PI/2:0;}
 for(let n=0;n<8;n++){const a=n*2.4,x=W.sites.jungle.x+Math.sin(a)*32,z=W.sites.jungle.z+Math.cos(a)*32;this.resource('damp-log-'+n,'spore',x,ground(x,z),z,'jungle',{type:'damp-log'});}
 if(W.bossContentEnabled){this.buildCave();this.buildShrine();this.buildShrineApproach();}buildSurvivalCaves(this);this.buildShop();this.buildJungle();
 const islandStone=this.mat('#c8c7b8',false,'cave-limestone').clone();islandStone.bumpMap=null;islandStone.onBeforeCompile=shader=>{shader.vertexShader='varying vec3 islandPosition;varying vec3 islandNormal;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nislandPosition=position;islandNormal=normal;');shader.fragmentShader='varying vec3 islandPosition;varying vec3 islandNormal;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <map_fragment>',`#ifdef USE_MAP
vec3 iw=pow(abs(normalize(islandNormal)),vec3(4.));iw/=max(.001,iw.x+iw.y+iw.z);diffuseColor*=mapTexelToLinear(texture2D(map,islandPosition.zy/4.)*iw.x+texture2D(map,islandPosition.xz/4.)*iw.y+texture2D(map,islandPosition.xy/4.)*iw.z);
#endif`);};islandStone.customProgramCacheKey=()=> 'island-stone-triplanar';this.islandGroups=[];islands.forEach((i,n)=>{const g=this.group(i.x,i.y,i.z);this.islandGroups.push({i,g});const top=this.mesh(g,'cylinder','#bdc5aa',0,-.35,0,i.r,.7,i.r,false,'moss-stone');top.userData.islandTop=n;
 const profile=[new T.Vector2(0,-18),new T.Vector2(i.r*.28,-13),new T.Vector2(i.r*.73,-7),new T.Vector2(i.r,-.3)];const rockGeo=new T.LatheGeometry(profile,40);const pos=rockGeo.attributes.position;for(let k=0;k<pos.count;k++){const x=pos.getX(k),z=pos.getZ(k),y=pos.getY(k);const f=1+.08*Math.sin(x*.8+z*.6+y*1.2);pos.setXYZ(k,x*f,y,z*f);}rockGeo.computeVertexNormals();const rock=new T.Mesh(rockGeo,islandStone);rock.castShadow=true;rock.receiveShadow=true;g.add(rock);
 for(let j=0;j<(i.variant===3?8:3);j++){const a=j*Math.PI/4,x=Math.cos(a)*i.r*.78,z=Math.sin(a)*i.r*.78;this.mesh(g,'rock','#91d8df',x,-3,z,.6,2.1,.6,true,'blue-crystal');this.tube(g,[[x,0,z],[x*.9,-4,z],[x*.7,-8,z*.8],[x*.85,-11,z*.8]],.12,'#7c6c4f','timber');}
 const trees=this.group(0,0,0,g);trees.userData={east:i.x+W.anchor.x,north:i.z+W.anchor.z,owned:[]};this.native.vegetation.build(trees,[{east:-i.r*.5,north:-i.r*.3,altitude:0,scale:n===2?1.1:.7,autumn:false,conifer:false},{east:i.r*.45,north:i.r*.25,altitude:0,scale:.7,autumn:false,conifer:true}],hash,()=>0);
 if(i.variant===2)for(const x of[-4,4]){this.mesh(g,'box','#8e9c99',x,2,0,1.2,4,1.2,false,'ancient-runes');this.mesh(g,'box','#8e9c99',x,4.1,0,2,.3,2,false,'moss-stone');}if(i.variant===4)for(let k=0;k<6;k++){const a=k*1.05;this.mesh(g,'box','#8e9c99',Math.cos(a)*6,.7,Math.sin(a)*6,2,1.4,1,false,'moss-stone');}if(i.variant===5){const arch=new T.Mesh(new T.TorusGeometry(4,.6,8,24,Math.PI),this.mat('#8e9c99',false,'ancient-runes'));arch.position.y=.2;g.add(arch);} });
 if(W.bossContentEnabled)D.bosses.filter(b=>b.biome!=='sky'&&b.biome!=='cave').forEach(b=>this.ruin(b.x,ground(b.x,b.z),b.z,12,b.color));
 }
 label(parent,text){const canvas=document.createElement('canvas');canvas.width=768;canvas.height=112;const ctx=canvas.getContext('2d');ctx.fillStyle='#102b2bea';ctx.fillRect(0,0,768,112);ctx.strokeStyle='#bfa671';ctx.lineWidth=3;ctx.strokeRect(2,2,764,108);ctx.fillStyle='#eee9cf';ctx.font='28px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,384,56,730);const texture=new T.CanvasTexture(canvas);texture.encoding=T.sRGBEncoding;const mat=new T.SpriteMaterial({map:texture,depthTest:false,sizeAttenuation:false});const sprite=new T.Sprite(mat);sprite.position.y=2.5;sprite.scale.set(.36,.0525,1);sprite.userData.transient=true;parent.add(sprite);return sprite;}
 // Each resource has a persistent habitat and a separate harvestable part.
 resource(id,kind,x,y,z,b,source={}){const root=this.group(x,y,z),g=this.group(0,0,0,root);const m=(parent,k,c,px,py,pz,sx,sy,sz,tex,glow=false)=>this.mesh(parent,k,c,px,py,pz,sx,sy,sz,glow,tex);const h=(px,pz)=>source.type==='cave-wall'?0:ground(x+px,z+pz)-y;
 const branch=(parent,ax,ay,az,bx,by,bz,r=.07)=>{const a=new T.Vector3(ax,ay,az),b=new T.Vector3(bx,by,bz),d=b.clone().sub(a),o=m(parent,'cylinder','#aa9070',...(a.add(b).multiplyScalar(.5).toArray()),r,d.length(),r,'bark');o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());return o;};
 const log=()=>{branch(root,-1.6,h(-1.6,0)+.2,0,1.4,h(1.4,0)+.2,.25,.24);branch(root,.4,.32,.12,1,.85,.8,.07);};
 const rockBase=()=>{for(let i=0;i<3;i++){const px=(i-1)*.65,pz=i%2*.35;const o=m(root,'shard','#bbb6a3',px,h(px,pz)+.12,pz,.95,.65,.72,'cave-limestone');o.rotation.y=i*1.7;}};
 if(kind==='wood'){if(source.type==='deadwood')log();for(let i=0;i<3;i++){const px=-.5+i*.4,pz=.6+i*.17;branch(g,px-.4,h(px-.4,pz)+.06,pz,px+.65,h(px+.65,pz+.25)+.07,pz+.25,.045);branch(g,px,h(px,pz)+.08,pz,px+.18,h(px+.18,pz+.5)+.07,pz+.5,.025);}}
 else if(kind==='stone'){if(source.type==='outcrop')rockBase();for(let i=0;i<5;i++){const px=Math.sin(i*2.4)*.75,pz=.9+Math.cos(i*2.4)*.45;const o=m(g,'shard','#b1b1a6',px,h(px,pz)+.07,pz,.19+i*.025,.08,.15+i*.025,'cave-limestone');o.rotation.y=i*2.1;}}
 else if(kind==='ore'){rockBase();for(let i=0;i<8;i++){const a=i*.8,px=Math.sin(a)*.68,pz=.55+Math.cos(a)*.12;const o=m(g,'shard',i%2?'#9f6c45':'#b39472',px,.28+(i%3)*.16,pz,.23,.1,.05,'forged-iron');o.rotation.z=a*.5;}}
 else if(kind==='crystal'){rockBase();for(let i=0;i<5;i++){const o=m(g,'cone','#a6cbe4',(i-2)*.23,.45+(i%2)*.15,.5+Math.sin(i)*.2,.12,.7+(i%3)*.35,.12,'blue-crystal',true);o.rotation.z=(i-2)*.15;}}
 else if(kind==='resin'){for(let i=0;i<4;i++)m(g,'sphere','#cf9d44',Math.sin(i)*.1,1.1+i*.12,0,.065,.12,.025,'brass');}
 else if(kind==='fiber'){for(let i=0;i<9;i++){const a=i*2.4,px=Math.sin(a)*.3,pz=Math.cos(a)*.3,py=h(px,pz);branch(g,px,py,pz,px+.15,py+.55+i%3*.1,pz,.009);const leaf=m(g,'leaf','#879956',px+.09,py+.35+i%3*.07,pz,.045,.4,1);leaf.rotation.set(-.2,a,.3);leaf.material.side=T.DoubleSide;}}
 else if(kind==='berry'){for(let i=0;i<5;i++){const a=i*1.3,px=Math.sin(a)*.55,pz=Math.cos(a)*.5;branch(root,0,0,0,px,.9+i%2*.25,pz,.025);for(let n=0;n<3;n++){const leaf=m(root,'leaf','#6f8b50',px*n/3,.4+n*.18,pz*n/3,.16,.08,1);leaf.rotation.set(.4,a,n);leaf.material.side=T.DoubleSide;}for(let n=0;n<3;n++)m(g,'sphere','#ae4c42',px+n*.055,.88+i%2*.25,pz,.045,.05,.045);}}
 else if(kind==='spore'){if(source.type==='damp-log')log();for(let i=0;i<5;i++){const px=-.5+i*.25,pz=.6+Math.sin(i)*.18,py=h(px,pz);m(g,'cylinder','#bab7a2',px,py+.13,pz,.025,.26,.025);m(g,'sphere','#978b9f',px,py+.28,pz,.14,.05,.14,false,true);}}
 const r={id,kind,x,y,z,biome:b,source,mesh:g,root,chunkKey:source.chunkKey};this.resources.push(r);return r;}
 syncResourceHabitats(){
 for(const [key,chunk] of this.resourceChunks){if(this.native.chunks.get(key)!==chunk||chunk.userData.distant){for(const r of this.resources.filter(r=>r.chunkKey===key))this.static.remove(r.root);this.resources=this.resources.filter(r=>r.chunkKey!==key);this.resourceChunks.delete(key);}}
 for(const [key,chunk] of this.native.chunks){if(chunk.userData.distant||this.resourceChunks.has(key))continue;this.resourceChunks.set(key,chunk);const {east,north,trees=[]}=chunk.userData,column=east/128,row=north/128;const safe=(x,z)=>!inCave(x,z)&&ground(x,z)>W.water+1&&Math.hypot(x,z)>25&&Math.hypot(x-W.shop.x,z-W.shop.z)>9;
 const put=(kind,x,z,index,source)=>{if(!safe(x,z))return;this.resource('hab-'+column+'-'+row+'-'+kind+'-'+index,kind,x,ground(x,z),z,biome(x,z,ground(x,z)),{...source,chunkKey:key});};
 for(let n=0;n<Math.min(4,trees.length);n++){const t=trees[Math.floor(n*trees.length/Math.min(4,trees.length))],tx=east+t.east-W.anchor.x,tz=north+t.north-W.anchor.z;put('wood',tx+1.4,tz+1,n,{type:'tree-base',anchor:{x:tx,z:tz}});if(n===0&&safe(tx,tz)){chunk.updateWorldMatrix(true,true);const trunks=[];chunk.traverse(o=>{if(o.isMesh&&o.material===this.native.vegetation.trunkBark)trunks.push(o);});const ray=new T.Raycaster(new T.Vector3(tx,ground(tx,tz)+1.3,tz+t.scale*2),new T.Vector3(0,0,-1),0,t.scale*4),hit=ray.intersectObjects(trunks,false)[0];if(hit)this.resource('hab-'+column+'-'+row+'-resin-'+n,'resin',hit.point.x,hit.point.y-1.3,hit.point.z+.02,biome(tx,tz,ground(tx,tz)),{type:'tree-trunk',anchor:{x:tx,z:tz},chunkKey:key});}if(n===1)put('berry',tx+2.6,tz-1.6,n,{type:'forest-edge',anchor:{x:tx,z:tz}});if(n===2)put('fiber',tx-2,tz+2,n,{type:'undergrowth',anchor:{x:tx,z:tz}});}
 for(let n=0;n<4;n++){const rx=east+hash(column,row,7000+n)*128-W.anchor.x,rz=north+hash(column,row,7100+n)*128-W.anchor.z,scale=.65+Math.pow(hash(column,row,n*3+2),.7)*1.3,b=W.nativeBiome(rx,rz);if(!safe(rx,rz))continue;put('stone',rx+scale*2,rz,n,{type:'rock-foot',anchor:{x:rx,z:rz}});if(n===0&&(b==='alpine'||b==='desert'||W.slope(rx,rz,8)>6))put('ore',rx+scale*1.65,rz,n,{type:'rock-vein',anchor:{x:rx,z:rz}});}
 // Low riverbanks grow reeds; wet gravel supports stones, never loose ore.
 for(let n=0;n<3;n++){const x=east+hash(column,row,8800+n)*128-W.anchor.x,z=north+hash(column,row,8900+n)*128-W.anchor.z,h=ground(x,z);if(h>W.water+.5&&h<W.water+3&&!inCave(x,z)){put('fiber',x,z,n+10,{type:'riverbank'});put('stone',x+1,z+1,n+10,{type:'riverbank'});}}
 }
 }

 ruin(x,y,z,r,color){const g=this.group(x,y,z);for(let n=0;n<7;n++){const a=n/7*Math.PI*2,px=Math.cos(a)*r,pz=Math.sin(a)*r,py=y>ground(x,z)+15?0:ground(x+px,z+pz)-y;this.mesh(g,'cylinder','#8e9c99',px,py+1.4,pz,.75,2.8,.75,false,W.nativeBiome(x,z)==='desert'?'sandstone':'ancient-runes');this.mesh(g,'box','#aeb8a8',px,py+3,pz,1.7,.4,1.7,false,'moss-stone');this.mesh(g,'rock',color,px,py+3.7,pz,.35,.65,.35,true,'blue-crystal');}
 const ring=this.mesh(g,'ring','#adbaa8',0,8,0,r*.6,r*.6,r*.6,false,'ancient-runes');ring.rotation.x=.2;this.deco.push(ring);}
 buildShrine(){const s=W.shrine,g=this.group(s.x,s.y,s.z);let low=s.y;for(let n=0;n<24;n++){const a=n*Math.PI/12;low=Math.min(low,ground(s.x+Math.cos(a)*7,s.z+Math.sin(a)*7));}const depth=s.y-low+.7;this.mesh(g,'cylinder','#8e9c99',0,-depth/2,0,7,depth,7,false,'moss-stone');this.mesh(g,'cylinder','#8e9c99',0,-.25,0,7,.8,7);this.mesh(g,'cylinder','#4b6869',0,.4,0,3,.8,3);this.mesh(g,'rock','#c9e4dc',0,1.8,0,.7,1.2,.7,true);this.sockets=[];for(let i=0;i<5;i++){const a=i/5*Math.PI*2,x=Math.sin(a)*4,z=Math.cos(a)*4;this.mesh(g,'cylinder','#354d50',x,.8,z,.6,1.6,.6);const socket=this.mesh(g,'rock','#4f6b70',x,1.9,z,.42,.65,.42);this.sockets.push(socket);}const ring=this.mesh(g,'ring','#91aaa2',0,7,0,5,5,5,false,'ancient-runes');this.deco.push(ring);}
 buildShop(){const s=W.shop,g=this.group(s.x,s.y,s.z);this.mesh(g,'box','#856246',0,.8,0,5,1.6,2);for(let x of[-2.5,2.5])this.mesh(g,'cylinder','#79583f',x,2,0,.12,4,.12);this.mesh(g,'box','#d3a65f',0,4,0,6,.12,4,false,'leather');const head=this.mesh(g,'sphere','#cd9d77',0,2.6,-.6,.3,.38,.3);for(const x of[-.1,.1])this.mesh(g,'sphere','#302e29',x,2.65,-.32,.035,.035,.035);this.mesh(g,'cylinder','#456b70',0,1.85,-.6,.45,1.2,.32,false,'leather');this.mesh(g,'cone','#c6aa74',0,3.1,-.6,.65,.5,.65,false,'leather');for(let i=0;i<4;i++)this.mesh(g,'rock',['#e9b95c','#8ee0d0','#baa2e0','#bcdd8b'][i],-1.6+i,1.8,.1,.2,.25,.2,false,'blue-crystal');}
 buildJungle(){const site=W.sites.jungle,trees=[],g=this.group(site.x,0,site.z);g.userData={east:site.x+W.anchor.x,north:site.z+W.anchor.z,owned:[]};for(let n=0;n<65;n++){const a=n*2.399,r=22+hash(n,98)*58,x=Math.sin(a)*r,z=Math.cos(a)*r,h=ground(site.x+x,site.z+z);if(h<W.water+2||window.KomorebiSurvivalPlacement.excludeTree(site.x+x+W.anchor.x,site.z+z+W.anchor.z))continue;trees.push({east:x,north:z,altitude:h,scale:1.2+hash(n,97)*.6,autumn:false,conifer:false});if(n%3===0){this.tube(g,[[x,h+9,z],[x+.8,h+6,z+.2],[x-.4,h+3,z+.5],[x+.3,h+.4,z]],.075,'#73865b','timber');}this.colliders.push({x:site.x+x,z:site.z+z,r:.7,minY:h,maxY:h+10});}this.native.vegetation.build(g,trees,hash,(x,z)=>NatureWorld.height(x,z)-W.anchor.y);}
 buildCave(){const c=W.sites.cave,g=this.group(c.x,W.caveY,c.z),r=W.caveHalf;let low=W.caveY;for(let x=-r;x<=r;x+=4)for(let z=-r;z<=r;z+=4)low=Math.min(low,ground(c.x+x,c.z+z));const depth=W.caveY-low+.7;this.mesh(g,'box','#a2a8ab',0,-depth/2,0,r*2,depth,r*2,false,'cave-limestone');
 this.mesh(g,'box','#a2a8ab',0,-.25,0,r*2,.5,r*2,false,'cave-limestone');
 const wall=(dx,dz,sx,sz)=>{const m=this.mesh(g,'box','#7d858d',dx,5.5,dz,sx,11,sz,false,'cave-limestone');this.colliders.push({x:c.x+dx,z:c.z+dz,sx:sx/2+.4,sz:sz/2+.4,minY:W.caveY-1,maxY:W.caveY+13});};wall(-r,0,3,r*2+3);wall(r,0,3,r*2+3);wall(0,-r,r*2+3,3);wall(-15,r,16,3);wall(15,r,16,3);
 for(let n=0;n<44;n++){const a=n/44*Math.PI*2;if(Math.sin(a)>.94)continue;const x=Math.cos(a)*(r+1),z=Math.sin(a)*(r+1);const m=this.mesh(g,'rock','#8a9194',x,3+hash(n,60)*3,z,4+hash(n,63)*3,6+hash(n,61)*5,4+hash(n,62)*3,false,'cave-limestone');m.rotation.y=n;}
 this.mesh(g,'box','#757e84',0,12,0,r*2+5,2,r*2+5,false,'cave-limestone');for(let n=0;n<32;n++){const x=-r+hash(n,70)*r*2,z=-r+hash(n,71)*r*2;this.mesh(g,'rock','#8d979a',x,13,z,5,2+hash(n,72)*2,5,false,'cave-limestone');this.mesh(g,'cone','#adb4bc',x,10,z,.5,-3-hash(n,73)*3,.5,false,'cave-limestone');}
 const ramp=new T.PlaneGeometry(10,20,2,12);ramp.rotateX(-Math.PI/2);const pos=ramp.attributes.position;for(let i=0;i<pos.count;i++){const z=pos.getZ(i)+10,t=z/20;pos.setY(i,W.rampHeight(c.x+pos.getX(i),c.z+r+z)-W.caveY);pos.setZ(i,z+r);}ramp.computeVertexNormals();const rm=new T.Mesh(ramp,this.mat('#92989b',false,'moss-stone'));rm.receiveShadow=true;rm.userData.caveRamp=true;g.add(rm);
 const light=new T.PointLight('#939df0',1.8,60);light.position.set(0,6,0);g.add(light);for(let n=0;n<9;n++){const x=-16+hash(n,75)*32,z=-15+hash(n,76)*30;this.mesh(g,'cone','#829bdb',x,2,z,.8,4,.8,true,'blue-crystal');} }
 enemy(def){const g=this.group(def.x,def.y,def.z,this.dynamic),boss=!!def.boss,c=def.color,limbs=[];let rig=null,body,head;
 const kind=def.kind,scale=boss?2.6:1;
 if(['beast','brute','flyer'].includes(kind)&&!(def.biome==='cave'&&kind==='flyer')){const wanted=kind==='flyer'?'eagle':def.biome==='jungle'?'jaguar':def.biome==='snow'?'wolf':boss?'bear':'wolf';const base=Wildlife.species.find(s=>s.id===wanted)||Wildlife.species.find(s=>s.id==='wolf');const spec={...base,id:'survival-'+def.id,scale:base.scale*(boss?2.4:1.2),color:boss?c:base.color};rig=Wildlife.create(spec,this.native.originals.fur);rig.detailDistance=8;g.add(rig.model);body=rig.model;head=rig.model;rig.flightActivity=kind==='flyer'?1:0;if(boss){for(let n=0;n<10;n++){const a=n/10*Math.PI*2;this.mesh(g,'rock',c,Math.cos(a)*1.1,2.3,Math.sin(a)*1.5,.3,.6,.3,true,'blue-crystal');}}}
 else if(kind==='golem'||def.final){body=this.mesh(g,'rock',c,0,1.6,0,.8,1.15,.5,false,def.final?'obsidian':'cave-limestone');head=this.mesh(g,'rock',c,0,2.9,0,.5,.6,.5,false,def.final?'obsidian':'cave-limestone');for(const x of[-1,1]){const arm=this.group(x,2.2,0,g);this.mesh(arm,'rock',c,0,-.4,0,.35,.75,.35,false,'moss-stone');this.mesh(arm,'rock',c,0,-1.1,0,.38,.4,.38,false,'cave-limestone');limbs.push(arm);const leg=this.group(x*.45,.9,0,g);this.mesh(leg,'rock',c,0,-.35,0,.3,.65,.3,false,'cave-limestone');limbs.push(leg);}this.mesh(g,'rock',def.final?'#ffb353':'#b8cafa',0,1.7,-.51,.3,.45,.1,true,def.final?'obsidian':'blue-crystal');for(let i=0;i<6;i++)this.mesh(g,'cone','#d8c38e',Math.sin(i*1.05)*.4,3.6,Math.cos(i*1.05)*.4,.09,.8,.09,false,'bone');g.scale.setScalar(boss?1.9: .85);}
 else if(kind==='crawler'||kind==='burrow'){body=this.mesh(g,'sphere',c,0,.7,0,.8,.45,1.05,false,'scale-hide');head=this.mesh(g,'sphere',c,0,.6,-1,.45,.3,.5,false,'scale-hide');for(let n=0;n<8;n++){const side=n%2?1:-1,z=(Math.floor(n/2)-1.5)*.45;const leg=this.group(side*.5,.65,z,g);this.tube(leg,[[0,0,0],[side*.7,.2,.1],[side*1.2,-.5,.3]],.07,c,'scale-hide');limbs.push(leg);}const tail=this.tube(g,[[0,.7,.8],[0,1.3,1.4],[0,2.1,1.1],[0,2.3,.5]],.12,c,'scale-hide');this.mesh(g,'cone','#e6d1a4',0,2.25,.35,.14,.6,.14,false,'bone');g.scale.setScalar(scale);}
 else if(kind==='spitter'){body=this.mesh(g,'sphere','#647b4e',0,1.2,0,.6,1.3,.6,false,'wild-fur');head=this.mesh(g,'sphere',c,0,2.5,0,.6,.45,.6,false,'scale-hide');for(let n=0;n<12;n++){const a=n/12*Math.PI*2;const petal=this.mesh(g,'sphere',c,Math.sin(a)*.85,2.5+Math.cos(n)*.15,Math.cos(a)*.85,.32,.12,.7,false,'leather');petal.rotation.y=a;petal.rotation.x=.35;limbs.push(petal);}for(let n=0;n<5;n++){const a=n/5*Math.PI*2;this.tube(g,[[0,1,0],[Math.sin(a)*.7,.5,Math.cos(a)*.7],[Math.sin(a)*1.3,.1,Math.cos(a)*1.3]],.1,'#63734f','timber');}g.scale.setScalar(boss?1.8:.8);}
 else if(kind==='flyer'){body=this.mesh(g,'sphere','#7c7174',0,.7,0,.3,.6,.25,false,'wild-fur');head=this.mesh(g,'sphere','#9a8780',0,1.15,-.1,.27,.3,.25,false,'wild-fur');for(const side of[-1,1]){const shape=new T.Shape();shape.moveTo(0,0);shape.bezierCurveTo(side*.6,.8,side*1.2,.7,side*1.8,.3);shape.quadraticCurveTo(side*1.2,.2,side*1.3,-.4);shape.quadraticCurveTo(side*.6,.1,0,-.4);const mesh=new T.Mesh(new T.ShapeGeometry(shape,14),this.mat('#8a757e',false,'leather').clone());mesh.material.side=T.DoubleSide;mesh.position.set(0,.7,0);g.add(mesh);limbs.push(mesh);}}
 else{body=this.mesh(g,'sphere',c,0,.6,0,.9,.65,.8,false,'blue-crystal');head=body;body.material=body.material.clone();body.material.roughness=.3;body.material.transparent=true;body.material.opacity=.86;for(let n=0;n<7;n++){const a=n*.9;this.mesh(g,'sphere',c,Math.sin(a)*.55,.35,Math.cos(a)*.55,.3,.2,.3,false,'blue-crystal');}}
 if(!rig)for(const x of[-.18,.18])this.mesh(g,'sphere','#f9dba2',x,(kind==='golem'||def.final?3:kind==='spitter'?2.55:kind==='crawler'||kind==='burrow'?.72:kind==='flyer'?1.2:.9),kind==='crawler'||kind==='burrow'?-1.4:-.45,.07,.07,.07,true);
 return{mesh:g,limbs,body,head,rig};}
 structure(s){const g=this.group(s.x,s.y,s.z,this.dynamic);if(s.type==='campfire'){for(let n=0;n<8;n++){const a=n*Math.PI/4;this.mesh(g,'rock','#858881',Math.cos(a)*.7,.15,Math.sin(a)*.7,.25,.2,.25);}for(let n=0;n<3;n++){const log=this.mesh(g,'cylinder','#704830',0,.2,0,.15,1.4,.15);log.rotation.set(Math.PI/2,0,n*Math.PI/3);}const flame=this.mesh(g,'cone','#ffb35b',0,.7,0,.45,1.3,.45,true);flame.visible=!!s.lit;const light=new T.PointLight('#ffb45d',1.5,14);light.position.y=1.8;light.visible=!!s.lit;g.add(light);g.userData.flame=flame;g.userData.light=light;}
 if(s.type==='house'){for(const x of[-3.7,3.7])for(const z of[-3.2,3.2]){const below=Math.max(.4,s.y-ground(s.x+x,s.z+z));this.mesh(g,'box','#8e7255',x,-below/2,z,.45,below,.45);}if(s.progress<1){const wire=new T.LineSegments(new T.EdgesGeometry(new T.BoxGeometry(8,5.8,7)),new T.LineBasicMaterial({color:'#b4dfd0',transparent:true,opacity:.28}));wire.position.y=2.9;wire.userData.transient=true;g.add(wire);}this.mesh(g,'box','#8e7255',0,.15,0,8,.3,7);for(let x of[-3.7,3.7])for(let z of[-3.2,3.2])this.mesh(g,'box','#68523f',x,2,z,.3,4,.3);if(s.progress>.25){this.mesh(g,'box','#a48660',0,2,-3.2,7.6,3.6,.2);for(let x of[-3.7,3.7])this.mesh(g,'box','#a48660',x,2,0,.2,3.6,6.5);}if(s.progress>.55)for(let x of[-2.5,2.5])this.mesh(g,'box','#98734e',x,2,3.2,2.6,3.6,.2);if(s.progress>.8){for(const side of[-1,1]){const roof=this.mesh(g,'box','#b9c7bb',side*2.15,5.05,0,4.8,.18,8.2,false,'shingles');roof.rotation.z=-side*.49;}const shape=new T.Shape();shape.moveTo(-4.2,0);shape.lineTo(4.2,0);shape.lineTo(0,2.3);shape.closePath();const geo=new T.ShapeGeometry(shape);for(const z of[-3.25,3.25]){const front=new T.Mesh(geo,this.mat('#bba78d',false,'timber'));front.material.side=T.DoubleSide;front.position.set(0,4,z);g.add(front);}this.mesh(g,'box','#8e7255',0,6.15,0,.2,.2,8.2);}if(s.progress>=1){this.mesh(g,'box','#dbc296',2,.6,-1.4,2,.5,3);this.mesh(g,'box','#738f8a',2,.9,-1.3,1.8,.2,2.4);}}
 if(s.type==='chest'){this.mesh(g,'box','#94704b',0,.6,0,1.8,1.2,1.2);this.mesh(g,'box','#c7aa61',0,.65,.62,.3,.4,.08);}
 return g;}

 floor(x,z,y,state){let h=W.floor(x,z,y);for(const s of state.structures){if(s.type==='house'&&Math.abs(x-s.x)<=4&&Math.abs(z-s.z)<=3.5&&y>=s.y-.1)h=Math.max(h,s.y+.3);}return h;}
 blocked(x,z,y,state){if(Math.abs(x)>100000||Math.abs(z)>100000)return true;if(y-ground(x,z)>-1&&y-ground(x,z)<12&&!this.native.canMove(x+W.anchor.x,z+W.anchor.z))return true;for(const c of this.colliders){if(c.minY!==undefined&&(y<c.minY-1||y>c.maxY))continue;if(c.r?Math.hypot(x-c.x,z-c.z)<c.r+.35:Math.abs(x-c.x)<c.sx&&Math.abs(z-c.z)<c.sz)return true;}for(const s of state.structures){if(s.type!=='house'||s.progress<.3||y>s.y+4.1)continue;let dx=x-s.x,dz=z-s.z;if(Math.abs(dx)<4.1&&Math.abs(dz)<3.6&&(Math.abs(dx)>3.35||dz<-2.85||dz>2.85&&Math.abs(dx)>1.05))return true;}return false;}
 update(t,state,environment={day:.36}){this.native.update(state.x+W.anchor.x,state.z+W.anchor.z,t,environment);this.nativeRoot.position.set(this.native.offset.x-W.anchor.x,-W.anchor.y,this.native.offset.z-W.anchor.z);this.syncResourceHabitats();for(const {i,g}of this.islandGroups||[])g.visible=Math.hypot(i.x-state.x,i.z-state.z)<2200;for(const {c,g} of this.caveGroups||[])g.visible=!!g.userData.terrainPatch||Math.hypot(c.x-state.x,c.z-state.z)<480;for(const r of this.resources){r.root.visible=Math.hypot(r.x-state.x,r.z-state.z)<140;r.mesh.visible=!(state.depleted[r.id]>state.time);}for(let i=0;i<(this.sockets?.length||0);i++)this.sockets[i].material=this.mat(state.inserted.includes(D.bosses[i].stone)?D.bosses[i].color:'#354f52',state.inserted.includes(D.bosses[i].stone),'blue-crystal');for(const r of this.deco)r.rotation.z=t*.025;}
}
window.EmberWorld=World;
})();
